    });
  }
}

export function registerIssueDependencyListeners(): Unsubscribe {
  const offStatus = subscribe("issue.status_changed", async (event) => {
    if (event.from !== "done" && event.from !== "canceled" && (event.to === "done" || event.to === "canceled")) {
